<script setup>
import { ref, reactive } from 'vue'
const emit = defineEmits(['signed-in'])
const stage = ref('password'), error = ref(''), code = ref(''), showPassword = ref(false)
const form = reactive({ username: 'admin@example.com', password: '' })
function submitPassword() {
  if (!form.username.trim() || !form.password) { error.value = 'Enter an example username and any non-empty demo password.'; return }
  form.password = ''; showPassword.value = false; error.value = ''; stage.value = 'totp'
}
function submitTotp() {
  if (code.value !== '123456') { error.value = 'For this simulated flow, use the example code 123456.'; return }
  code.value = ''; form.username = ''; error.value = ''; stage.value = 'done'; emit('signed-in')
}
function reset() { stage.value = 'password'; code.value = ''; form.password = ''; error.value = '' }
</script>
<template>
  <main class="w-full pt-16 min-h-screen" style="background: rgb(var(--c-surface))">
    <section class="login-layout"><div class="context"><p class="ax-label">AxionPanel / access design</p><h1>Sign in</h1><p class="intro">A deliberate entry point.<br>One password. A second factor.</p><p class="ax-sub">This is an interactive design preview, not an authentication service. It never connects to a server or creates a session.</p><div class="context-details"><div><span aria-hidden="true" class="material-symbols-outlined">lock</span><div><strong>Keep real credentials out</strong><p class="ax-sub">Use any invented password. Input is cleared between steps and is never saved.</p></div></div><div><span aria-hidden="true" class="material-symbols-outlined">verified_user</span><div><strong>Two-stage flow, simulated</strong><p class="ax-sub">Password entry → authenticator code → preview dashboard.</p></div></div></div><span class="ax-pill ax-pill-warn">Preview only · no identity verification</span></div>
      <section class="ax-card login-panel" aria-labelledby="login-step-title"><div class="step-strip"><span :class="{ current: stage === 'password' }">01 / Password</span><span :class="{ current: stage === 'totp' }">02 / Verification</span></div><div class="login-content"><p class="ax-label">{{ stage === 'password' ? 'Welcome to the preview' : stage === 'totp' ? 'Second factor / simulated' : 'Design flow complete' }}</p><h2 id="login-step-title" class="ax-title">{{ stage === 'password' ? 'Enter example credentials' : stage === 'totp' ? 'Verify with an example code' : 'Preview access enabled' }}</h2>
        <form v-if="stage === 'password'" autocomplete="off" @submit.prevent="submitPassword"><div class="ax-field"><label for="login-username" class="ax-label">Example username</label><input id="login-username" v-model="form.username" class="ax-input" autocomplete="off" placeholder="admin@example.com" required></div><div class="ax-field"><label for="login-password" class="ax-label">Demo password (anything invented)</label><div class="password-field"><input id="login-password" v-model="form.password" class="ax-input" :type="showPassword ? 'text' : 'password'" autocomplete="new-password" placeholder="Not your real password" required><button type="button" class="reveal" :aria-label="showPassword ? 'Hide demo password' : 'Show demo password'" @click="showPassword = !showPassword"><span aria-hidden="true" class="material-symbols-outlined">{{ showPassword ? 'visibility_off' : 'visibility' }}</span></button></div></div><p v-if="error" class="error" role="alert">{{ error }}</p><button class="ax-btn ax-btn-primary submit">Continue · Preview only<span aria-hidden="true" class="material-symbols-outlined">arrow_forward</span></button><p class="ax-sub">No password is checked, transmitted, or persisted.</p></form>
        <form v-else-if="stage === 'totp'" autocomplete="off" @submit.prevent="submitTotp"><p class="ax-sub">In the real product, you would open an authenticator app. Here, enter the public example code below.</p><div class="example-code"><span class="ax-label">Simulated code</span><strong class="ax-mono">123 456</strong></div><div class="ax-field"><label for="login-code" class="ax-label">Six-digit example code</label><input id="login-code" v-model="code" class="ax-input code" inputmode="numeric" maxlength="6" autocomplete="off" placeholder="123456" required></div><p v-if="error" class="error" role="alert">{{ error }}</p><button class="ax-btn ax-btn-primary submit">Enter design preview · Preview only<span aria-hidden="true" class="material-symbols-outlined">arrow_forward</span></button><button type="button" class="ax-btn ax-btn-ghost back" @click="reset">Back to password</button></form>
        <div v-else role="status"><span class="ax-pill ax-pill-info">Preview only</span><p class="ax-sub">The parent shell can now open the preview dashboard. No real login or secure session has occurred.</p><button class="ax-btn ax-btn-ghost" @click="reset">Restart example flow</button></div>
      </div><footer class="login-footer ax-sub"><span aria-hidden="true" class="material-symbols-outlined">science</span>Design sandbox · Credentials are not saved</footer></section>
    </section>
  </main>
</template>
